package main

import (
	"fmt"
)

// Sum دو عدد رو جمع می‌زنه
func Sum(a, b int) int {
	return a + b
}

// Factorial فاکتوریل یک عدد غیرمنفی رو حساب می‌کنه
func Factorial(n int) int {
	if n < 0 {
		return -1
	}
	if n == 0 {
		return 1
	}
	result := 1
	for i := 2; i <= n; i++ {
		result *= i
	}
	return result
}

func main() {
	fmt.Println("=== تست تابع Sum ===")
	fmt.Printf("Sum(3, 5) = %d (انتظار: 8)\n", Sum(3, 5))
	fmt.Printf("Sum(-2, 10) = %d (انتظار: 8)\n", Sum(-2, 10))

	fmt.Println("\n=== تست تابع Factorial ===")
	for i := 0; i <= 5; i++ {
		fmt.Printf("Factorial(%d) = %d\n", i, Factorial(i))
	}

	// چک‌های ساده (assertion)
	passed := true
	if Sum(2, 2) != 4 {
		fmt.Println("❌ خطا: Sum(2,2)")
		passed = false
	} else {
		fmt.Println("✅ Sum(2,2) درسته")
	}

	if Factorial(5) != 120 {
		fmt.Println("❌ خطا: Factorial(5)")
		passed = false
	} else {
		fmt.Println("✅ Factorial(5) درسته")
	}

	if Factorial(0) != 1 {
		fmt.Println("❌ خطا: Factorial(0)")
		passed = false
	} else {
		fmt.Println("✅ Factorial(0) درسته")
	}

	if passed {
		fmt.Println("\n🎉 همه تست‌ها با موفقیت پاس شدند!")
	} else {
		fmt.Println("\n⚠️ بعضی تست‌ها ناموفق بودند.")
	}
}
